'use strict';
window.AdminExtra=(()=>{
const A=Admin,{node,button,esc}=A;
function targets(row){const rows=row?[row]:A.selectedRows;if(!rows.length)A.toast('请先选择要操作的记录');return rows;}
function changeField(label,row,field,options){const rows=targets(row);if(!rows.length)return;const form=node('form','form-grid'),f={label:field,required:true,controls:[{type:options?.length?'select':'text'}]},box=A.fieldControl(f,'',form);if(options?.length){const old=box.querySelector('[data-field]'),select=node('select');select.dataset.field=field;select.required=true;select.append(new Option('请选择',''));options.forEach(o=>select.append(new Option(o,o)));old.replaceWith(select);}form.append(box);A.showDialog(label,form,[{label:'取消',run:A.closeDialog},{label:'保存',cls:'primary',run:()=>{if(!form.reportValidity())return;const value=form.querySelector('[data-field]').value;for(const r of rows){const i=A.matchColumn(field,A.getTable().headers);if(i>=0)r.cells[i]=value;r.extra={...r.extra,[field]:value};}A.persist(label,rows.length+' 条');A.closeDialog();A.renderResults();A.toast('已更新本地记录');}}]);}
function localStatus(label,row){if(!row)return;A.confirmAction(label,'对象：'+(row.cells.find(Boolean)||A.source.label),()=>{const h=A.getTable().headers,i=h.findIndex(x=>x==='状态'||x==='菜单状态');const map={暂停:'已暂停',继续:'进行中',取消:'已取消',隐藏:'隐藏',显示:'启用',重试:'待重试','删除已发布':'已删除'};if(i>=0)row.cells[i]=map[label]||label;row.extra={...row.extra,'本地操作':label};row.actions=row.actions.map(a=>a===label?(label==='暂停'?'继续':label==='继续'?'暂停':a):a);A.persist(label,row.cells.find(Boolean));A.renderResults();A.toast('本地状态已更新');});}
function receiptPreview(row,label){const div=node('div');div.append(node('p','form-note',label+' · 本地演示'));const dl=node('dl','detail-grid');A.getTable().headers.forEach((h,i)=>{if(h&&h!=='操作')dl.append(node('dt','',h),node('dd','',row.cells[i]||'—'));});div.append(dl);A.showDialog(label,div,[{label:'关闭',run:A.closeDialog}]);}
function sourceOptions(field){const captured=A.optionsFor('专属销售','assign');if(captured.length)return captured;const p=A.pageData('salesManage'),table=p?.tables?.[0],i=table?.headers?.indexOf('销售姓名');return i>=0?[...new Set(table.rows.map(r=>r.cells[i]).filter(Boolean))]:['演示销售 1','演示销售 2'];}
function navAssignment(label){const form=node('form'),grid=node('div','form-grid');const target=node('select'),source=node('select');A.nav.tenants.forEach(t=>{target.append(new Option(t.name,t.id,false,t.id===A.tenant));source.append(new Option(t.name,t.id));});target.setAttribute('aria-label','目标企业');source.setAttribute('aria-label','复制来源企业');const tl=node('label','field');tl.append(node('span','','目标企业'),target);grid.append(tl);if(label==='复制菜单'){const sl=node('label','field');sl.append(node('span','','复制来源企业'),source);grid.append(sl);}form.append(node('p','form-note',label==='增量更新菜单'?'保留目标已有菜单，再添加勾选入口。':label==='批量删减菜单'?'从目标企业当前导航中移除勾选入口。':label==='复制菜单'?'复制来源企业中目标企业也支持的菜单入口；目标企业专属内容不会被错误套用。':'使用勾选结果替换目标企业的本地导航。'),grid);const tree=node('div','tree-checks');form.append(tree);const read=t=>window.AdminMenuState.read(t,A.navStorageKey(t.id)).enabled;function draw(){const t=A.nav.tenants.find(t=>t.id===target.value),enabled=new Set(read(t)),from=new Set(read(A.nav.tenants.find(t=>t.id===source.value)));tree.replaceChildren();t.menu.forEach(g=>{const d=node('details');d.open=true;d.append(node('summary','',g.label));(g.children||[g]).forEach(l=>{const line=node('label','check-field'),c=node('input');c.type='checkbox';c.value=l.route;c.checked=label==='批量删减菜单'||label==='增量更新菜单'?false:label==='复制菜单'?from.has(l.route):enabled.has(l.route);line.append(c,document.createTextNode(l.label+(enabled.has(l.route)?'（当前显示）':'')));d.append(line);});tree.append(d);});}target.onchange=source.onchange=draw;draw();A.showDialog(label,form,[{label:'取消',run:A.closeDialog},{label:'预览变更',cls:'primary',run:()=>{const t=A.nav.tenants.find(t=>t.id===target.value),current=read(t),chosen=[...tree.querySelectorAll('input:checked')].map(i=>i.value);let next=label==='增量更新菜单'?[...new Set([...current,...chosen])]:label==='批量删减菜单'?current.filter(r=>!chosen.includes(r)):chosen;if(!next.length){A.toast('请至少保留一个菜单入口');return;}const leaves=t.menu.flatMap(g=>g.children||[g]),added=next.filter(r=>!current.includes(r)),removed=current.filter(r=>!next.includes(r));const labelOf=r=>leaves.find(l=>l.route===r)?.label||r;const box=node('div');box.append(node('p','',t.name+'：'+current.length+' 项 → '+next.length+' 项'),node('p','hint','新增：'+(added.map(labelOf).join('、')||'无')),node('p','hint','隐藏：'+(removed.map(labelOf).join('、')||'无')));A.closeDialog();A.showDialog('确认本地导航变化',box,[{label:'取消',run:A.closeDialog},{label:'应用',cls:'primary',run:()=>{let saved;try{saved=JSON.parse(localStorage.getItem(A.navStorageKey(t.id))||'{}');}catch{saved={};}localStorage.setItem(A.navStorageKey(t.id),JSON.stringify({...saved,enabled:next}));A.persist(label,t.name);A.closeDialog();parent.postMessage({type:'admin-navigation-updated',tenant:t.id},location.origin);A.toast('本地导航已更新');}}]);}}]);}
function editMenu(row){const form=node('form','form-grid'),table=A.getTable();const labels=['菜单名称','菜单状态','超级权限','排序'];labels.forEach(label=>{const i=table.headers.indexOf(label);form.append(A.fieldControl({label,required:label==='菜单名称',controls:[{type:label==='排序'?'number':label==='菜单状态'?'radio':label==='超级权限'?'checkbox':'text',checked:true}],options:label==='菜单状态'?['显示','隐藏']:undefined},row.cells[i]||'',form));});A.showDialog('修改菜单',form,[{label:'取消',run:A.closeDialog},{label:'保存',cls:'primary',run:()=>{if(!form.reportValidity())return;const values=Object.fromEntries([...form.querySelectorAll('[data-field]')].map(i=>[i.dataset.field,i.dataset.single?i.querySelector('input:checked')?.value||'':i.type==='checkbox'?(i.checked?'是':'否'):i.value]));for(const [k,v]of Object.entries(values)){const i=table.headers.indexOf(k);if(i>=0)row.cells[i]=v;}const t=A.nav.tenants.find(t=>t.id===A.tenant),all=t.menu.flatMap(g=>[g,...(g.children||[])]),item=all[Number(row.id.split('-')[1])];let saved;try{saved=JSON.parse(localStorage.getItem(A.navStorageKey(A.tenant))||'{}');}catch{saved={};}saved.labels??={};saved.order??={};saved.enabled??=t.menu.flatMap(g=>g.children||[g]).map(l=>l.route);if(item){const id=item.route||item.id;saved.labels[id]=values['菜单名称'];saved.order[id]=Number(values['排序']);const routes=(item.children||[item]).map(l=>l.route);if(/停用|禁用|隐藏/.test(values['菜单状态']))saved.enabled=saved.enabled.filter(r=>!routes.includes(r));else saved.enabled=[...new Set([...saved.enabled,...routes])];}if(!saved.enabled.length){A.toast('请至少保留一个菜单入口');return;}localStorage.setItem(A.navStorageKey(A.tenant),JSON.stringify(saved));A.persist('编辑菜单',values['菜单名称']);A.closeDialog();parent.postMessage({type:'admin-navigation-updated',tenant:A.tenant},location.origin);A.renderResults();}}]);}
function analysis(label){const form=node('form','form-grid');const customers=A.pageData('yxCustomerList')||A.pageData('customerManagement');const names=customers?.tables?.[0]?.rows.map(r=>r.cells[1]).filter(Boolean)||['演示客户 1'];const select=node('select');select.required=true;select.setAttribute('aria-label','选择客户');names.slice(0,20).forEach(n=>select.append(new Option(n,n)));const note=node('textarea');note.placeholder='需要关注的沟通问题（本地演示）';form.append(select,note);A.showDialog(label,form,[{label:'取消',run:A.closeDialog},{label:'生成演示结果',cls:'primary',run:()=>{const t=A.getTable(),r={id:'local-'+crypto.randomUUID(),cells:t.headers.map(()=>''),actions:['详情'],extra:{'结果性质':'合成演示，不是客户真实评分','关注问题':note.value}};t.headers.forEach((h,i)=>{r.cells[i]=h==='客户'?select.value:h==='人设'?'演示工作账号':h==='总分'?'80':h==='总评'?'演示：信息说明清楚，可继续确认预约意向':h==='触发方式'?'手动演示':h==='打分时间'?new Date().toLocaleString('sv-SE'):h==='结果质量'?'演示样本':'';});t.rows.unshift(r);A.persist('生成演示分析',select.value);A.closeDialog();A.renderResults();A.toast('已生成本地演示结果');}}]);}
function saveTag(){const form=node('form');const field=A.fieldControl({label:'标签名称',required:true,controls:[{type:'text'}]},'',form);form.append(field);A.showDialog('保存筛选为标签',form,[{label:'取消',run:A.closeDialog},{label:'保存',cls:'primary',run:()=>{if(!form.reportValidity())return;A.model.savedFilters??=[];const name=form.querySelector('input').value;A.model.savedFilters.push({name,filters:A.filters,count:A.filteredRows().length});A.persist('保存筛选标签',name);A.closeDialog();A.showDialog('已保存的筛选标签',node('p','form-note',A.model.savedFilters.map(t=>t.name+' · '+t.count+' 条样本').join('\n')),[{label:'关闭',run:A.closeDialog}]);}}]);}
function dictionary(row){const form=node('form'),input=node('textarea');input.style.cssText='width:100%;min-height:250px';input.value=row.extra?.['字典内容']||JSON.stringify([{key:'create',label:'创建'},{key:'update',label:'编辑'},{key:'delete',label:'删除'}],null,2);form.append(node('p','form-note','以下为本地字典项演示，可编辑键名与显示名称。'),input);A.showDialog('管理日志字典',form,[{label:'取消',run:A.closeDialog},{label:'保存',cls:'primary',run:()=>{try{const d=JSON.parse(input.value);if(!Array.isArray(d)||d.some(x=>!x.key||!x.label))throw Error();row.extra={...row.extra,'字典内容':JSON.stringify(d,null,2)};const i=A.getTable().headers.indexOf('字典项数量');if(i>=0)row.cells[i]=String(d.length);A.persist('编辑日志字典',row.cells[0]);A.closeDialog();A.renderResults();}catch{input.setCustomValidity('请输入包含 key 和 label 的 JSON 数组');input.reportValidity();}}}]);}
function downloadTemplate(){const cols=A.route==='uploadCustomerList'?['手机号','昵称','添加备注']:A.getTable().headers.filter(h=>h&&h!=='操作');const url=URL.createObjectURL(new Blob(['\uFEFF'+cols.join(',')+'\r\n'],{type:'text/csv;charset=utf-8'})),a=node('a');a.href=url;a.download=A.source.label+'-模板.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);A.toast('CSV 模板已下载');}
function action(label,row){
 if(/^(添加子级|加子项)$/.test(label)&&row){A.edit();const form=A.$('dialogBody');const parentField=[...form.querySelectorAll('[data-field]')].find(e=>/父级|父项目|上级/.test(e.dataset.field));const name=row.cells[A.getTable().headers.findIndex(h=>/名称/.test(h))]||row.cells.find(Boolean);if(parentField){if(parentField.tagName==='SELECT'&&![...parentField.options].some(o=>o.value===name))parentField.append(new Option(name,name));parentField.value=name;}return true;}
 if(label==='重试'&&!row){A.renderResults();A.toast('已重新载入本地样本');return true;}
 if(A.route==='allMenu'&&/同步菜单|复制菜单|增量更新菜单|批量删减菜单/.test(label)){navAssignment(label);return true;}
 if(A.route==='menu'&&row&&label==='编辑'){editMenu(row);return true;}
 if(/^(暂停|继续|取消|隐藏|显示|重试|删除已发布)$/.test(label)&&row){localStatus(label,row);return true;}
 if(/专属销售|改派/.test(label)){changeField(label,row,'专属销售',sourceOptions('销售'));return true;}
 if(/批量分组/.test(label)){changeField(label,row,'所在分组',A.optionsFor('群组'));return true;}
 if(/批量修改大类/.test(label)){changeField(label,row,'大类',A.optionsFor('大类','edit'));return true;}
 if(/批量设置分佣/.test(label)){changeField(label,row,'分佣信息',['按商品默认规则','固定金额','按比例']);return true;}
 if(label==='修改标题'){changeField(label,row,'标题');return true;}
 if(label==='标签管理'){changeField(label,row,'标签内容');return true;}
 if(label==='保存为标签'){saveTag();return true;}
 if(/下载.*模板/.test(label)){downloadTemplate();return true;}
 if(/发起分析|批量分析/.test(label)){analysis(label);return true;}
 if(A.route==='auditDict'&&row&&label==='管理'){dictionary(row);return true;}
 if(label==='记录'&&row){const object=row.cells.find(Boolean);const events=(A.model.history||[]).filter(e=>e.object===object);const body=node('div');if(events.length)body.append(node('p','form-note',events.map(e=>e.time+' '+e.action).join('\n')));else body.append(A.empty('暂无此记录的本地操作历史','修改当前记录后可在这里查看。'));A.showDialog('记录',body,[{label:'关闭',run:A.closeDialog}]);return true;}
 if(/预览|明细|查看回复|查看原因|查看全部|查看更多|展开|发送通知详情/.test(label)&&row){receiptPreview(row,label);return true;}
 if(label==='飞书通知'&&row){A.showDialog('通知预览',node('p','form-note',row.cells.join('\n')),[{label:'关闭',run:A.closeDialog},{label:'保存本地通知预览',cls:'primary',run:()=>{A.persist('保存通知预览',row.cells[0]);A.closeDialog();A.toast('预览已保存，未发送真实通知');}}]);return true;}
 if(label==='同步商品'){A.confirmAction('同步商品','将当前租户已有商品样本复制到本地小程序商品列表。',()=>{const src=A.pageData('products')?.tables?.[0],target=A.getTable();if(src)for(const row of src.rows){const copy={id:'local-'+crypto.randomUUID(),cells:target.headers.map(h=>row.cells[src.headers.indexOf(h)]||''),actions:['详情']};target.rows.push(copy);}A.persist('模拟商品同步');A.renderResults();A.toast(src?'本地商品样本已同步':'当前租户暂无可同步的商品样本');});return true;}
 if(label==='同步标签'){A.showDialog('同步标签',node('p','form-note','将本页标签结构保存为本地同步样本。不会修改任何线上客户标签。'),[{label:'取消',run:A.closeDialog},{label:'确认本地同步',cls:'primary',run:()=>{A.model.lastLocalSync=new Date().toISOString();A.persist('本地标签同步');A.closeDialog();A.toast('已记录本地同步结果');}}]);return true;}
 if(label==='索引列表'&&row){receiptPreview(row,'环境索引详情');return true;}
 if(label==='创建索引'){const form=node('form','form-grid');['企业','表名','alias'].forEach(label=>form.append(A.fieldControl({label,required:true,controls:[{type:'text'}]},'',form)));A.showDialog('创建本地索引任务',form,[{label:'取消',run:A.closeDialog},{label:'创建演示任务',cls:'primary',run:()=>{if(!form.reportValidity())return;const t=A.model.tables[0],r={id:'local-'+crypto.randomUUID(),cells:t.headers.map(()=>''),actions:[]};form.querySelectorAll('[data-field]').forEach(c=>{const i=t.headers.indexOf(c.dataset.field);if(i>=0)r.cells[i]=c.value;});t.headers.forEach((h,i)=>{if(h==='状态')r.cells[i]='演示完成';if(h==='进度')r.cells[i]='100%';if(h==='更新时间')r.cells[i]=new Date().toLocaleString('sv-SE');});t.rows.unshift(r);A.persist('创建索引演示');A.closeDialog();A.renderResults();}}]);return true;}
 return false;
}
return {action};
})();
